package app.camotrack.android.hajin.scan

import kotlin.math.abs
import kotlin.math.max
import kotlin.math.min

/**
 * Reads a stack count from a straightened 200 px tile: the white digits in
 * its top-right corner, split into blobs and matched against templates of
 * the game's digits. Ingredient stacks run 1 to 10. (HajinStackCount.)
 */
object StackCount {
    private class Glyph(var minX: Int, var minY: Int, var maxX: Int, var maxY: Int) {
        val xs = ArrayList<Int>(); val ys = ArrayList<Int>()
        val width get() = maxX - minX + 1
        val height get() = maxY - minY + 1
    }

    fun read(tile: Raster): Int? {
        val corner = tile.cropped(Box(96.0, 0.0, 104.0, 96.0)) ?: return null
        val w = corner.width; val h = corner.height
        val low = IntArray(w * h) { min(corner.r(it), min(corner.g(it), corner.b(it))) }
        // Every brightness cut-off gives a reading; keep the ones that make a
        // real stack count (1 to 10) and take the one that best fits the
        // digit shapes. A digit broken into pieces fits badly, so it loses.
        var best: Pair<Int, Double>? = null
        var fallback: String? = null
        var sawTen = false
        for (threshold in listOf(195, 180, 165, 150, 135)) {
            val chain = digitChain(components(low, w, h, threshold), w, h)
            if (chain.isEmpty()) continue
            val reads = chain.map { classify(it) }
            val text = reads.joinToString("") { it.first }
            if (fallback == null) fallback = text
            val n = text.toIntOrNull() ?: continue
            if (n !in 1..10) continue
            if (n == 10) sawTen = true
            val fit = reads.sumOf { it.second } / reads.size
            if (best == null || fit < best.second) best = n to fit
        }
        // A 10 seen at any cut-off beats a 1: a stray 0 can't come from
        // nowhere, but a real one is easily lost
        if (best?.first == 1 && sawTen) return 10
        if (best != null) return best.first
        val last = fallback?.lastOrNull() ?: return null
        val n = last.toString().toIntOrNull() ?: return null
        return if (n > 0) n else null
    }

    private fun components(low: IntArray, w: Int, h: Int, threshold: Int): List<Glyph> {
        val seen = BooleanArray(w * h)
        val out = ArrayList<Glyph>()
        val stack = IntArray(w * h)
        for (start in 0 until w * h) {
            if (low[start] <= threshold || seen[start]) continue
            var top = 0
            stack[top++] = start; seen[start] = true
            val g = Glyph(w, h, 0, 0)
            while (top > 0) {
                val i = stack[--top]
                val x = i % w; val y = i / w
                g.xs.add(x); g.ys.add(y)
                g.minX = min(g.minX, x); g.maxX = max(g.maxX, x); g.minY = min(g.minY, y); g.maxY = max(g.maxY, y)
                for ((nx, ny) in arrayOf(x + 1 to y, x - 1 to y, x to y + 1, x to y - 1)) {
                    if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue
                    val j = ny * w + nx
                    if (!seen[j] && low[j] > threshold) { seen[j] = true; stack[top++] = j }
                }
            }
            out.add(g)
        }
        return out
    }

    /** The digits: tall-enough blobs on one line, the rightmost and any just
     *  to its left (at most two). */
    private fun digitChain(all: List<Glyph>, w: Int, h: Int): List<Glyph> {
        // Blobs touching the crop's edge, or hairline-thin, are the tile's border
        var cs = all.filter {
            it.height > h * 0.28 && it.height < h * 0.9 && it.width < w * 0.45 &&
                it.minX > 1 && it.width >= it.height * 0.18
        }
        // At the right edge: the tile's border, unless it's a digit's height and width
        val digitHeight = cs.filter { it.maxX < w - 2 }.maxOfOrNull { it.height } ?: 0
        cs = cs.filter {
            it.maxX < w - 2 || (digitHeight > 0 && abs(it.height - digitHeight) < digitHeight / 4 && it.width >= it.height * 0.35)
        }
        val tallest = cs.maxByOrNull { it.height } ?: return emptyList()
        val mid = (tallest.minY + tallest.maxY) / 2.0
        val sorted = cs.filter { abs((it.minY + it.maxY) / 2.0 - mid) < tallest.height * 0.4 }
            .sortedBy { it.minX }.toMutableList()
        val chain = ArrayList<Glyph>()
        chain.add(sorted.removeAt(sorted.size - 1))
        while (sorted.isNotEmpty()) {
            val c = sorted.removeAt(sorted.size - 1)
            val last = chain[0]
            // crisp screenshot digits sit a little further apart than a photo's
            if (!((last.minX - c.maxX) < last.height * 0.6 && abs((c.height - last.height).toDouble()) < last.height * 0.25)) break
            chain.add(0, c)
        }
        return chain.takeLast(2)
    }

    /** The glyph box-averaged onto a W x H grid: a cell is on when at least
     *  half its source area is. */
    private fun grid(g: Glyph, W: Int, H: Int): BooleanArray {
        val on = BooleanArray(g.width * g.height)
        for (k in g.xs.indices) on[(g.ys[k] - g.minY) * g.width + (g.xs[k] - g.minX)] = true
        val gw = g.width.toDouble(); val gh = g.height.toDouble()
        val out = BooleanArray(W * H)
        for (j in 0 until H) {
            val sy0 = j * gh / H; val sy1 = (j + 1) * gh / H
            for (i in 0 until W) {
                val sx0 = i * gw / W; val sx1 = (i + 1) * gw / W
                var total = 0.0; var covered = 0.0
                var yy = sy0.toInt()
                while (yy < min(g.height, (sy1 - 1e-9).toInt() + 1)) {
                    val fy = min(sy1, yy + 1.0) - max(sy0, yy.toDouble())
                    var xx = sx0.toInt()
                    while (xx < min(g.width, (sx1 - 1e-9).toInt() + 1)) {
                        val a = (min(sx1, xx + 1.0) - max(sx0, xx.toDouble())) * fy
                        total += a
                        if (on[yy * g.width + xx]) covered += a
                        xx++
                    }
                    yy++
                }
                out[j * W + i] = total > 0 && covered / total >= 0.5
            }
        }
        return out
    }

    /** Enclosed background areas: 0 has one, 8 has two, 1 has none. */
    private fun holes(b: BooleanArray, w: Int, h: Int): Int {
        val seen = BooleanArray(w * h); var n = 0
        val stack = IntArray(w * h)
        for (start in 0 until w * h) {
            if (b[start] || seen[start]) continue
            var top = 0
            stack[top++] = start; seen[start] = true
            var edge = false; var size = 0
            while (top > 0) {
                val i = stack[--top]
                size++
                val x = i % w; val y = i / w
                if (x == 0 || y == 0 || x == w - 1 || y == h - 1) edge = true
                for ((nx, ny) in arrayOf(x + 1 to y, x - 1 to y, x to y + 1, x to y - 1)) {
                    if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue
                    val j = ny * w + nx
                    if (!b[j] && !seen[j]) { seen[j] = true; stack[top++] = j }
                }
            }
            if (!edge && size >= 6) n++
        }
        return n
    }

    private fun classify(g: Glyph): Pair<String, Double> {
        val bits = grid(g, 12, 20)
        val h = holes(grid(g, 24, 40), 24, 40)
        val aspect = g.width.toDouble() / g.height
        var best = "" to Double.POSITIVE_INFINITY
        for (t in templates) {
            var d = 0.0
            for (k in bits.indices) if (bits[k] != (t.bits[k] == '1')) d += 1
            d += abs(aspect - t.aspect) * 60 + (if (h == t.holes) 0 else 80)
            if (d < best.second) best = t.digit to d
        }
        return best
    }

    private class Template(val digit: String, val bits: String, val holes: Int, val aspect: Double)

